<template><section class="builder-panel controls-panel"><header class="builder-panel__heading"><strong>Test & Controls</strong><small>Browser only</small></header><div class="test-grid"><button v-for="item in tests" :key="item.type" @click="$emit('test',item)">{{ item.icon }} {{ item.label }}</button></div><div class="demo-chat-control"><button type="button" :disabled="!chatSelected||chatLocked" title="Moves Unified Chat locally for filming" @click="$emit('demo-chat-move')">⠿ Demo Chat Move</button><small>Demo action · browser only</small></div><div class="control-row"><button @click="$emit('undo')">↶ Undo</button><button @click="$emit('redo')">↷ Redo</button><label><input :checked="paused" type="checkbox" @change="$emit('pause',$event.target.checked)"> Pause</label></div><div class="control-row"><label><input :checked="grid" type="checkbox" @change="$emit('grid',$event.target.checked)"> Grid</label><label><input :checked="snapping" type="checkbox" @change="$emit('snapping',$event.target.checked)"> Snapping</label><label><input :checked="safeZone" type="checkbox" @change="$emit('safe-zone',$event.target.checked)"> Safe Zone</label></div><div class="reset-row"><button @click="$emit('reset-scene')">Reset Scene</button><button class="danger" @click="$emit('reset-all')">Reset Full Demo</button></div></section></template>
<script setup>defineProps({paused:Boolean,grid:Boolean,snapping:Boolean,safeZone:Boolean,chatSelected:Boolean,chatLocked:Boolean});defineEmits(['test','pause','grid','snapping','safe-zone','undo','redo','reset-scene','reset-all','demo-chat-move']);const tests=[['stream.follow','alerts','♥','Test Follow'],['stream.subscription','subscription-alert','★','Test Subscription'],['stream.raid','raid-alert','⚡','Test Raid'],['achievement.unlocked','achievement','🏆','Test Achievement'],['community.event.upcoming','upcoming-event','▣','Test Event'],['tts.requested','tts','▥','Test TTS'],['chat.message','twitch-chat','◫','Test Chat']].map(([type,targetWidgetType,icon,label])=>({id:`test-${type}`,type,targetWidgetType,platform:type.startsWith('stream')||type.startsWith('tts')||type.startsWith('chat')?'twitch':'respawn',actor:'Demo Creator',summary:label,createdAtLabel:'just now',payload:{demo:true},icon,label}))</script>
